import React, { useState, useEffect } from 'react';
import {
  Container,
  Typography,
  Paper,
  Grid,
  Card,
  CardContent,
  Button,
  Box,
  Chip,
  Alert,
} from '@mui/material';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import { institutionsAPI } from '../services/api';

const InstitutionDashboard = () => {
  const { currentUser } = useAuth();
  const navigate = useNavigate();
  const [stats, setStats] = useState({
    totalApplications: 0,
    pendingApplications: 0,
    admittedStudents: 0,
    totalCourses: 0,
    totalFaculties: 0
  });
  const [recentApplications, setRecentApplications] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      const applicationsResponse = await institutionsAPI.getApplications();
      const applications = applicationsResponse.data || [];
      
      setStats({
        totalApplications: applications.length,
        pendingApplications: applications.filter(app => app.status === 'pending').length,
        admittedStudents: applications.filter(app => app.status === 'admitted').length,
        totalCourses: currentUser?.profile?.courses?.length || 0,
        totalFaculties: currentUser?.profile?.faculties?.length || 0
      });

      setRecentApplications(applications.slice(0, 5));
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'admitted': return 'success';
      case 'rejected': return 'error';
      case 'waiting_list': return 'warning';
      default: return 'default';
    }
  };

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Typography variant="h4" gutterBottom>
        Institution Dashboard
      </Typography>
      
      <Grid container spacing={3}>
        {/* Statistics Cards */}
        <Grid item xs={12} sm={6} md={2.4}>
          <Card>
            <CardContent sx={{ textAlign: 'center' }}>
              <Typography variant="h4" color="primary">
                {stats.totalApplications}
              </Typography>
              <Typography variant="body2" color="textSecondary">
                Total Applications
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={6} md={2.4}>
          <Card>
            <CardContent sx={{ textAlign: 'center' }}>
              <Typography variant="h4" color="warning.main">
                {stats.pendingApplications}
              </Typography>
              <Typography variant="body2" color="textSecondary">
                Pending Review
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={6} md={2.4}>
          <Card>
            <CardContent sx={{ textAlign: 'center' }}>
              <Typography variant="h4" color="success.main">
                {stats.admittedStudents}
              </Typography>
              <Typography variant="body2" color="textSecondary">
                Admitted Students
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={6} md={2.4}>
          <Card>
            <CardContent sx={{ textAlign: 'center' }}>
              <Typography variant="h4" color="info.main">
                {stats.totalCourses}
              </Typography>
              <Typography variant="body2" color="textSecondary">
                Courses
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={6} md={2.4}>
          <Card>
            <CardContent sx={{ textAlign: 'center' }}>
              <Typography variant="h4" color="secondary.main">
                {stats.totalFaculties}
              </Typography>
              <Typography variant="body2" color="textSecondary">
                Faculties
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        {/* Quick Actions */}
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Quick Actions
              </Typography>
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                <Button 
                  variant="contained" 
                  onClick={() => navigate('/institution/faculties')}
                  fullWidth
                >
                  Manage Faculties
                </Button>
                <Button 
                  variant="contained" 
                  onClick={() => navigate('/institution/courses')}
                  fullWidth
                >
                  Manage Courses
                </Button>
                <Button 
                  variant="outlined" 
                  onClick={() => navigate('/institution/applications')}
                  fullWidth
                >
                  View Applications
                </Button>
                <Button 
                  variant="outlined" 
                  onClick={() => navigate('/profile')}
                  fullWidth
                >
                  Update Profile
                </Button>
              </Box>
            </CardContent>
          </Card>
        </Grid>

        {/* Recent Applications */}
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Recent Applications
              </Typography>
              {recentApplications.length === 0 ? (
                <Typography variant="body2" color="textSecondary">
                  No applications yet
                </Typography>
              ) : (
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                  {recentApplications.map((application) => (
                    <Paper key={application.id} variant="outlined" sx={{ p: 1.5 }}>
                      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <Box>
                          <Typography variant="body2" fontWeight="bold">
                            {application.student?.personalInfo?.firstName} {application.student?.personalInfo?.lastName}
                          </Typography>
                          <Typography variant="body2" color="textSecondary">
                            {application.course?.name}
                          </Typography>
                        </Box>
                        <Chip 
                          label={application.status} 
                          color={getStatusColor(application.status)}
                          size="small"
                        />
                      </Box>
                    </Paper>
                  ))}
                </Box>
              )}
              {recentApplications.length > 0 && (
                <Button 
                  variant="text" 
                  onClick={() => navigate('/institution/applications')}
                  sx={{ mt: 1 }}
                  fullWidth
                >
                  View All Applications
                </Button>
              )}
            </CardContent>
          </Card>
        </Grid>

        {/* Institution Summary */}
        <Grid item xs={12}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Institution Summary
              </Typography>
              <Grid container spacing={2}>
                <Grid item xs={12} sm={6}>
                  <Typography variant="body2" color="textSecondary">
                    <strong>Name:</strong> {currentUser?.profile?.name || 'Not set'}
                  </Typography>
                  <Typography variant="body2" color="textSecondary">
                    <strong>Email:</strong> {currentUser?.email}
                  </Typography>
                  <Typography variant="body2" color="textSecondary">
                    <strong>Phone:</strong> {currentUser?.profile?.phone || 'Not set'}
                  </Typography>
                </Grid>
                <Grid item xs={12} sm={6}>
                  <Typography variant="body2" color="textSecondary">
                    <strong>Address:</strong> {currentUser?.profile?.address || 'Not set'}
                  </Typography>
                  <Typography variant="body2" color="textSecondary">
                    <strong>Status:</strong> {currentUser?.profile?.status || 'Active'}
                  </Typography>
                  <Typography variant="body2" color="textSecondary">
                    <strong>Description:</strong> {currentUser?.profile?.description ? 'Set' : 'Not set'}
                  </Typography>
                </Grid>
              </Grid>
            </CardContent>
          </Card>
        </Grid>
      </Grid>
    </Container>
  );
};

export default InstitutionDashboard;
